using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        var chatConfig = new ChatConfiguration(
            chatClientFactory: _ =>
            {
                // Use the same model configured in the app host for evaluation
                var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                    ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is not set.");
                var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";
                var credential = new Azure.Identity.DefaultAzureCredential();

                return new Azure.AI.OpenAI.AzureOpenAIClient(
                    new Uri(endpoint), credential)
                    .GetChatClient(deployment)
                    .AsIChatClient();
            },
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ]);

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"),
            chatConfiguration: chatConfig);
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await scenario.GetChatClient()!.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsGroundedAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await scenario.GetChatClient()!.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }
}

